sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-24 (D-05, D-23): vehicle from card, SUSPICIOUS on a lost card, match status, write-off notes
    var isInsert = current.operation() == 'insert';
    var errors = [];

    var amount = parseFloat(current.getValue('amount'));
    if (isNaN(amount) || amount <= 0) {
        errors.push('Amount must be greater than 0.');
    }
    if (current.getValue('match_status') == 'WRITTEN_OFF' && !(current.getValue('notes') || '').trim()) {
        errors.push('Notes are required to write off a fuel transaction.');
    }
    if (errors.length) {
        for (var i = 0; i < errors.length; i++) {
            gs.addErrorMessage(errors[i]);
        }
        current.setAbortAction(true);
        return;
    }

    if (isInsert) {
        var card = current.fuel_card.getRefRecord();
        if (card.isValidRecord()) {
            // Loss time = when the card was set to LOST (sys_updated_on of that change, FLEET-44)
            var lostAfter = card.getValue('status') == 'LOST' && !current.transaction_datetime.nil() &&
                new GlideDateTime(current.getValue('transaction_datetime')).compareTo(new GlideDateTime(card.getValue('sys_updated_on'))) > 0;
            if (lostAfter) {
                current.setValue('match_status', 'SUSPICIOUS'); // never auto-matched (D-23)
                current.setValue('vehicle', '');
                return;
            }
            if (current.vehicle.nil()) {
                current.setValue('vehicle', card.getValue('assigned_vehicle'));
            }
        }
    }

    var status = current.getValue('match_status');
    if (current.reservation.changes() || (isInsert && !current.reservation.nil())) {
        if (!current.reservation.nil() && status != 'WRITTEN_OFF') {
            current.setValue('match_status', 'MATCHED');
        } else if (current.reservation.nil() && status == 'MATCHED') {
            current.setValue('match_status', 'UNMATCHED');
        }
    }
})(current, previous);
